document.addEventListener("DOMContentLoaded", () => {
    const input = document.getElementById("wiki-search-input");
    const resultsContainer = document.getElementById("wiki-search-results");

    if (!input || !resultsContainer) {
        return;
    }

    let searchIndex = [];

    /*
     * Load the search index generated by the Python builder.
     */
    fetch("/search.json")
        .then(response => {
            if (!response.ok) {
                throw new Error(`Failed to load search index: ${response.status}`);
            }

            return response.json();
        })
        .then(data => {
            searchIndex = data;
        })
        .catch(error => {
            console.error("Wiki search:", error);
        });


    /*
     * Normalize text for searching.
     *
     * This makes searches case-insensitive and also handles
     * differences in whitespace.
     */
    function normalize(text) {
        return String(text || "")
            .toLowerCase()
            .trim()
            .replace(/\s+/g, " ");
    }


    /*
     * Escape text before inserting it into HTML.
     *
     * Titles and links ultimately originate from the vault, so
     * they should never be inserted into innerHTML unescaped.
     */
    function escapeHtml(text) {
        return String(text || "")
            .replace(/&/g, "&amp;")
            .replace(/</g, "&lt;")
            .replace(/>/g, "&gt;")
            .replace(/"/g, "&quot;")
            .replace(/'/g, "&#039;");
    }


    /*
     * Calculate how closely a page matches the search query.
     *
     * Higher score = better result.
     */
    function titleScore(item, query) {
        const title = normalize(item.title);
        const aliases = (item.aliases || []).map(normalize);

        // Exact title match
        if (title === query) {
            return 1000;
        }

        // Title starts with query
        if (title.startsWith(query)) {
            return 800;
        }

        // An alias exactly matches
        if (aliases.some(alias => alias === query)) {
            return 750;
        }

        // Alias starts with query
        if (aliases.some(alias => alias.startsWith(query))) {
            return 650;
        }

        // Query occurs somewhere in the title
        if (title.includes(query)) {
            return 500;
        }

        // Query occurs somewhere in an alias
        if (aliases.some(alias => alias.includes(query))) {
            return 450;
        }

        return 0;
    }


    /*
     * Determine whether this page links to something matching
     * the search query.
     *
     * This is what allows searches for nonexistent pages to
     * still return useful context.
     */
    function linkedPageMatches(item, query) {
        return (item.links || []).filter(link => {
            return normalize(link).includes(query);
        });
    }


    /*
     * Search the index.
     */
    function search(query) {
        query = normalize(query);

        if (!query) {
            return {
                direct: [],
                related: []
            };
        }

        const direct = [];
        const related = [];

        searchIndex.forEach(item => {
            const directScore = titleScore(item, query);

            if (directScore > 0) {
                direct.push({
                    item,
                    score: directScore
                });
                return;
            }

            const matchingLinks = linkedPageMatches(item, query);

            if (matchingLinks.length > 0) {
                related.push({
                    item,
                    matchingLinks
                });
            }
        });


        /*
         * Direct matches are sorted by relevance first,
         * then alphabetically.
         */
        direct.sort((a, b) => {
            if (b.score !== a.score) {
                return b.score - a.score;
            }

            return normalize(a.item.title)
                .localeCompare(normalize(b.item.title));
        });


        /*
         * Related pages are sorted alphabetically.
         */
        related.sort((a, b) => {
            return normalize(a.item.title)
                .localeCompare(normalize(b.item.title));
        });


        return { direct, related };
    }


    /*
     * Render one search result.
     */
    function renderResult(item, matchingLinks = []) {
        const title = escapeHtml(item.title);
        const category = escapeHtml(item.category || "");

        let relatedText = "";

        if (matchingLinks.length > 0) {
            relatedText = `
                <div class="wiki-search-result-links">
                    Links to:
                    ${matchingLinks
                        .map(link => `<strong>${escapeHtml(link)}</strong>`)
                        .join(", ")}
                </div>
            `;
        }

        return `
            <a
                class="wiki-search-result"
                href="${escapeHtml(item.url)}"
            >
                <div class="wiki-search-result-title">
                    ${title}
                </div>
            </a>
        `;

//        return `
//            <a
//                class="wiki-search-result"
//                href="${escapeHtml(item.url)}"
//            >
//                <div class="wiki-search-result-title">
//                    ${title}
//                </div>
//
//                ${category
//                    ? `<div class="wiki-search-result-category">${category}</div>`
//                    : ""}
//
//                ${relatedText}
//            </a>
//        `;
    }


    /*
     * Render the complete result list.
     */
    function renderResults(query) {
        const { direct, related } = search(query);

        if (!query) {
            resultsContainer.innerHTML = "";
            resultsContainer.hidden = true;
            return;
        }

        if (direct.length === 0 && related.length === 0) {
            resultsContainer.innerHTML = `
                <div class="wiki-search-no-results">
                    No results found for
                    <strong>${escapeHtml(query)}</strong>.
                </div>
            `;

            resultsContainer.hidden = false;
            return;
        }


        let html = "";


        /*
         * Direct title/alias matches.
         */
        if (direct.length > 0) {
            html += `
                <div class="wiki-search-section">
                    <div class="wiki-search-heading">
                        Pages
                    </div>

                    ${direct
                        .map(result => renderResult(result.item))
                        .join("")}
                </div>
            `;
        }


        /*
         * Pages which link to something matching the query.
         */
        if (related.length > 0) {
            html += `
                <div class="wiki-search-section wiki-search-related">
                    <div class="wiki-search-heading">
                        Related pages
                    </div>

                    ${related
                        .map(result =>
                            renderResult(
                                result.item,
                                result.matchingLinks
                            )
                        )
                        .join("")}
                </div>
            `;
        }


        resultsContainer.innerHTML = html;
        resultsContainer.hidden = false;
    }


    /*
     * Search while typing.
     */
    input.addEventListener("input", () => {
        renderResults(input.value);
    });


    /*
     * Escape closes the search results.
     */
    input.addEventListener("keydown", event => {
        if (event.key === "Escape") {
            input.value = "";
            renderResults("");
            input.blur();
        }
    });


    /*
     * Clicking elsewhere closes the result dropdown.
     */
    document.addEventListener("click", event => {
        if (
            !input.contains(event.target) &&
            !resultsContainer.contains(event.target)
        ) {
            resultsContainer.hidden = true;
        }
    });


    /*
     * Clicking the search box again shows the results.
     */
    input.addEventListener("focus", () => {
        if (input.value.trim()) {
            renderResults(input.value);
        }
    });
});